import random, math, time

# --- 1) Synthetic generator speed + shape (design-validation probe) ---
t0=time.time()
def gen(n, periods, noise, seed):
    r=random.Random(seed); out=[]
    for i in range(n):
        v=0.0002*i
        for (P,a) in periods: v+=a*math.sin(2*math.pi*i/P)
        out.append(v+r.gauss(0,noise))
    return out
s=gen(6000,[(24,1.0),(12,0.4)],0.1,7)
print("gen 6000 pts: %.3fs"%(time.time()-t0))

# --- 2) CycleNet per-phase aggregation cost ---
t0=time.time()
L=24; acc=[0.0]*L; cnt=[0]*L
for i,v in enumerate(s): acc[i%L]+=v; cnt[i%L]+=1
C=[acc[k]/cnt[k] for k in range(L)]
print("per-phase mean: %.4fs"%(time.time()-t0))

# --- 3) One pure-Python MLP fwd+bwd step: in=96, hid=64, out=96, batch=32 ---
random.seed(0)
LIN,HID,LOU,B=96,64,96,32
W1=[[random.gauss(0,0.1) for _ in range(HID)] for _ in range(LIN)]
W2=[[random.gauss(0,0.1) for _ in range(LOU)] for _ in range(HID)]
b1=[0.0]*HID; b2=[0.0]*LOU
def step(batch):
    gW1=[[0.0]*HID for _ in range(LIN)]; gw1=[0.0]*HID
    gW2=[[0.0]*LOU for _ in range(HID)]; gw2=[0.0]*LOU
    loss=0.0
    for x,y in batch:
        h=[sum(x[i]*W1[i][j] for i in range(LIN))+b1[j] for j in range(HID)]
        h=[v*(v>0) for v in h]
        o=[sum(h[j]*W2[j][k] for j in range(HID))+b2[k] for k in range(LOU)]
        loss+=sum((o[k]-y[k])**2 for k in range(LOU))/LOU
        go=[2*(o[k]-y[k])/LOU for k in range(LOU)]
        for j in range(HID):
            gj=sum(go[k]*W2[j][k] for k in range(LOU))
            if h[j]<=0: gj=0.0
            gw2[j]+=gj
            wr=W2[j]
            for k in range(LOU): gW2[j][k]+=gj*o[k]*0+gj*h[j]
        for i in range(LIN):
            xi=x[i]; gi=gW1[i]
            for j in range(HID):
                gj=sum(go[k]*W2[j][k] for k in range(LOU))*(1 if h[j]>0 else 0)
                gi[j]+=gj*xi
        for j in range(HID): gw1[j]+=sum(go[k]*W2[j][k] for k in range(LOU))*(1 if h[j]>0 else 0)
    return loss
batch=[([random.gauss(0,1) for _ in range(LIN)],[random.gauss(0,1) for _ in range(LOU)]) for _ in range(B)]
t0=time.time(); loss=step(batch); dt=time.time()-t0
print("one full-fwd+bwd step (incl grad recompute): %.2fs, loss=%.3f"%(dt,loss))
